# area: dunder_dispatch
# hypothesis: A class that declares __iter__ only as an annotation has no iteration protocol at runtime, so iterating an instance raises TypeError and a checker that accepts the for loop is unsound.
from collections.abc import Callable, Iterator


class Bag:
    __iter__: Callable[[], Iterator[int]]  # annotation only, no method

    def size(self) -> int:
        return 2


class Pair:
    def __iter__(self) -> Iterator[int]:
        yield 1
        yield 2


def try_iterate(b: Bag) -> str:
    try:
        for x in b:  # expect-error: Bag has no __iter__ on its type
            print(x)
    except TypeError:
        return 'TypeError'
    return 'iterated'


print(Bag().size())
print(try_iterate(Bag()))
print(list(Pair()))
